"  // Auto-fetch and poll hook for digital orders
  useEffect(() => {
    let pollInterval;
    if (activeTab === 'digital') {
      // Fetch riders
      posService.getRiders()
        .then(res => setRiders(res.data || []))
        .catch(err => console.error("Failed to fetch riders:", err));

      // Fetch digital orders
      fetchOrdersForMode(digitalDateMode, digitalStartDate, digitalEndDate);

      // Poll every 10 seconds for new online orders
      pollInterval = setInterval(() => {
        fetchOrdersForMode(digitalDateMode, digitalStartDate, digitalEndDate);
      }, 10000);
    }
    return () => {
      if (pollInterval) clearInterval(pollInterval);
    };
  }, [activeTab, digitalDateMode, digitalStartDate, digitalEndDate]);"

